public:
    int movesToChessboard(vector<vector<int>>& board) {
        int n = board.size();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if ((board[r][c] ^ board[0][c] ^ board[r][0] ^ board[0][0]) != 0) return -1;
            }
        }
        int row_ones = 0, col_ones = 0;
        for (int i = 0; i < n; i++) {
            row_ones += board[0][i];
            col_ones += board[i][0];
        }
        if (row_ones < n / 2 || row_ones > (n + 1) / 2) return -1;
        if (col_ones < n / 2 || col_ones > (n + 1) / 2) return -1;

        int row_diff = 0, col_diff = 0;
        for (int i = 0; i < n; i++) {
            if (board[i][0] != i % 2) row_diff++;
            if (board[0][i] != i % 2) col_diff++;
        }
        int row_moves, col_moves;
        if (n % 2 == 0) {
            row_moves = min(row_diff, n - row_diff) / 2;
            col_moves = min(col_diff, n - col_diff) / 2;
        } else {
            if (row_diff % 2 != 0) row_diff = n - row_diff;
            if (col_diff % 2 != 0) col_diff = n - col_diff;
            row_moves = row_diff / 2;
            col_moves = col_diff / 2;
        }
        return row_moves + col_moves;
    }
