var movesToChessboard = function(board) {
    const n = board.length;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            if ((board[r][c] ^ board[0][c] ^ board[r][0] ^ board[0][0]) !== 0) return -1;
        }
    }
    let rowOnes = 0, colOnes = 0;
    for (let i = 0; i < n; i++) {
        rowOnes += board[0][i];
        colOnes += board[i][0];
    }
    if (rowOnes < Math.floor(n / 2) || rowOnes > Math.floor((n + 1) / 2)) return -1;
    if (colOnes < Math.floor(n / 2) || colOnes > Math.floor((n + 1) / 2)) return -1;

    let rowDiff = 0, colDiff = 0;
    for (let i = 0; i < n; i++) {
        if (board[i][0] !== i % 2) rowDiff++;
        if (board[0][i] !== i % 2) colDiff++;
    }
    let rowMoves, colMoves;
    if (n % 2 === 0) {
        rowMoves = Math.floor(Math.min(rowDiff, n - rowDiff) / 2);
        colMoves = Math.floor(Math.min(colDiff, n - colDiff) / 2);
    } else {
        if (rowDiff % 2 !== 0) rowDiff = n - rowDiff;
        if (colDiff % 2 !== 0) colDiff = n - colDiff;
        rowMoves = Math.floor(rowDiff / 2);
        colMoves = Math.floor(colDiff / 2);
    }
    return rowMoves + colMoves;
};
